# Bank zadań autorskich — etap 2: wypracowania (partia 3: II wojna, świat i Polska po 1945 r., temat przekrojowy).
BANK = {}

M = 'Wypracowanie (wypowiedź argumentacyjna). Zadanie autorskie IndexLab w formacie egzaminu maturalnego od 2023 r. Twoja wypowiedź powinna liczyć minimum 300 wyrazów.'

BANK['umiejetnosci'] = [
 B('Wypracowanie — II wojna światowa: Polskie Państwo Podziemne', M,
   T('wypracowanie', 15, 'Polskie Państwo Podziemne było zjawiskiem wyjątkowym na tle okupowanej Europy. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt polityczny, wojskowy i społeczno-kulturowy.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa).\n\n'
     'W czasie II wojny światowej ruch oporu działał niemal w każdym okupowanym kraju — we Francji, Jugosławii czy Norwegii. Uważam jednak, że Polskie Państwo Podziemne było zjawiskiem wyjątkowym, bo nie było jedynie ruchem oporu, lecz konspiracyjnym państwem z własną władzą, wojskiem, sądami i szkolnictwem, podporządkowanym legalnemu rządowi na uchodźstwie.\n\n'
     'W aspekcie politycznym państwo podziemne zachowało ciągłość II Rzeczypospolitej. Rząd RP na uchodźstwie (najpierw we Francji, potem w Londynie) powołał w kraju Delegaturę Rządu na Kraj, a jej podziemną namiastką parlamentu była Rada Jedności Narodowej, skupiająca główne stronnictwa: PPS, Stronnictwo Ludowe, Stronnictwo Narodowe i Stronnictwo Pracy. Działały konspiracyjne odpowiedniki ministerstw, a sądy podziemne wydawały wyroki na zdrajców i szmalcowników. Takiej struktury nie miał żaden inny okupowany kraj.\n\n'
     'W aspekcie wojskowym Armia Krajowa, powstała w 1942 r. ze Związku Walki Zbrojnej, była największą armią podziemną okupowanej Europy — liczyła w 1944 r. ponad 300 tys. zaprzysiężonych żołnierzy. Prowadziła dywersję i sabotaż, wywiad (m.in. przekazanie aliantom informacji o rakietach V-1 i V-2) oraz akcje odwetowe, jak zamach na Franza Kutscherę (1944). Kulminacją była akcja „Burza” i Powstanie Warszawskie.\n\n'
     'W aspekcie społeczno-kulturowym państwo podziemne chroniło naród przed wyniszczeniem. Tajne nauczanie objęło setki tysięcy uczniów, działały tajne uniwersytety, wydawano setki tytułów prasy konspiracyjnej (np. „Biuletyn Informacyjny”). Rada Pomocy Żydom „Żegota” (1942) była jedyną taką organizacją w okupowanej Europie finansowaną przez rząd na uchodźstwie.\n\n'
     'Można wskazać, że także we Francji czy Jugosławii ruch oporu był liczny i skuteczny, a partyzanci Tity sami wyzwolili znaczną część kraju. Tamte ruchy nie tworzyły jednak całego aparatu państwa — sądownictwa, oświaty i administracji — ciągłego wobec przedwojennego rządu.\n\n'
     'Wyjątkowość widać też w zasięgu: struktury państwa podziemnego działały na całym obszarze przedwojennej Polski, zarówno pod okupacją niemiecką, jak i — w latach 1939–1941 i od 1944 r. — sowiecką, co w innych krajach się nie zdarzało.\n\n'
     'Podsumowując, Polskie Państwo Podziemne było wyjątkowe, bo w warunkach najbardziej brutalnej okupacji odtworzyło struktury państwa, a nie tylko prowadziło walkę zbrojną. Dlatego uważam tezę za prawdziwą.',
     'Plan: stanowisko „tak” → polityczny (rząd w Londynie, Delegatura, RJN, sądy podziemne) → wojskowy (ZWZ → AK 1942, liczebność, wywiad V-1/V-2, Kutschera, „Burza”) → społeczno-kulturowy (tajne nauczanie, prasa, „Żegota”) → kontrargument (Francja, Jugosławia) → wniosek.\n\nTypowe błędy: utożsamianie Państwa Podziemnego tylko z AK; pomijanie struktur cywilnych.')),

 B('Wypracowanie — II wojna światowa: Powstanie Warszawskie', M,
   T('wypracowanie', 15, 'Decyzja o wybuchu Powstania Warszawskiego była uzasadniona. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt militarny, polityczny i międzynarodowy.',
     'Modelowa odpowiedź (stanowisko: decyzja miała poważne racje polityczne, ale militarnie i międzynarodowo nie była uzasadniona).\n\n'
     'Powstanie Warszawskie wybuchło 1 sierpnia 1944 r. i trwało 63 dni. Zginęło w nim ok. 18 tys. powstańców i ok. 150–200 tys. cywilów, a lewobrzeżna Warszawa została niemal całkowicie zniszczona. Spór o sens tej decyzji trwa do dziś. Uważam, że powstańcy mieli ważne powody polityczne, ale warunki militarne i międzynarodowe nie dawały szans na sukces, dlatego decyzję trudno uznać za uzasadnioną.\n\n'
     'W aspekcie politycznym dowództwo AK i Delegatura chciały, by to Polacy wyzwolili stolicę i powitali Armię Czerwoną jako gospodarze, z legalną władzą podległą rządowi w Londynie. W lipcu 1944 r. powstał komunistyczny PKWN, a ZSRS nie uznawał rządu londyńskiego. Bez powstania władzę w Warszawie przejęliby komuniści. Do tego Niemcy zarządzili zbiórkę 100 tys. mężczyzn do kopania umocnień, a radio z Moskwy wzywało warszawiaków do walki — dowódcy obawiali się, że miasto zbuntuje się bez nich.\n\n'
     'W aspekcie militarnym powstanie było słabo przygotowane. Część broni wywieziono wcześniej na wschód w ramach akcji „Burza”, a na początku walk tylko niewielka część żołnierzy miała broń palną. Nie udało się zdobyć lotnisk, mostów ani dworców. Decyzję podjęto w pośpiechu (gen. Bór-Komorowski, po meldunku o czołgach sowieckich na Pradze), a Niemcy szybko przerzucili posiłki, w tym jednostki SS dokonujące rzezi ludności Woli.\n\n'
     'Decydujący był aspekt międzynarodowy. Plan zakładał szybkie wkroczenie Armii Czerwonej, ale Stalin zatrzymał ofensywę na linii Wisły i nie pozwolił samolotom alianckim lądować na lotniskach sowieckich. Zrzuty z Zachodu, lecących aż z Włoch, były zbyt małe. Wielka Brytania i USA nie zamierzały psuć relacji ze Stalinem dla sprawy Warszawy.\n\n'
     'Obrońcy decyzji podkreślają, że powstanie było wyrazem woli niepodległości i że bez niego komuniści przejęliby władzę bez oporu. Pamięć o powstaniu stała się jednym z fundamentów polskiej tożsamości. Nie zmienia to faktu, że jego cele polityczne nie zostały osiągnięte, a cena była ogromna.\n\n'
     'Podsumowując, decyzja o wybuchu powstania miała racjonalne przesłanki polityczne, ale nie uwzględniała realiów militarnych i postawy Stalina. Dlatego uważam tezę za nieprawdziwą.',
     'Plan: stanowisko „racje polityczne, ale nie uzasadniona” → polityczny (PKWN, legalna władza, apel niemiecki, radio moskiewskie) → militarny (brak broni, „Burza”, pośpiech, Wola) → międzynarodowy (Stalin, lotniska, zrzuty, postawa aliantów) → kontrargument (wola niepodległości, pamięć) → wniosek.\n\nTypowe błędy: emocjonalna ocena bez faktów; pomijanie roli PKWN. Oba stanowiska są dopuszczalne — liczą się argumenty.')),

 B('Wypracowanie — świat po 1945 r.: dekolonizacja', M,
   T('wypracowanie', 15, 'Dekolonizacja przyniosła narodom Azji i Afryki więcej korzyści niż strat. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt polityczny, gospodarczy i społeczny.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa, choć wiele nowych państw zapłaciło za niepodległość wysoką cenę).\n\n'
     'Po II wojnie światowej rozpadły się europejskie imperia kolonialne. W 1947 r. niepodległość uzyskały Indie i Pakistan, w 1949 r. Indonezja, a w 1960 r. — „roku Afryki” — aż 17 państw afrykańskich. Uważam, że mimo wielu trudności dekolonizacja przyniosła tym narodom więcej korzyści niż strat, bo dała im prawo do decydowania o sobie.\n\n'
     'W aspekcie politycznym najważniejszą korzyścią była niepodległość i prawo do samostanowienia, zapisane w Karcie Narodów Zjednoczonych. Byłe kolonie weszły do ONZ, a w ruchu państw niezaangażowanych (od 1961 r.) próbowały prowadzić własną politykę. Zarazem granice wyznaczone przez kolonizatorów często nie odpowiadały podziałom etnicznym, co prowadziło do konfliktów — podział Indii w 1947 r. kosztował setki tysięcy ofiar, a Kongo pogrążyło się w wojnie domowej. W wielu krajach władzę przejęły dyktatury wojskowe.\n\n'
     'W aspekcie gospodarczym nowe państwa przejmowały kontrolę nad swoimi surowcami — Egipt znacjonalizował Kanał Sueski (1956), a państwa naftowe utworzyły OPEC (1960). Część z nich, np. Indie, z czasem stała się ważnymi gospodarkami. Wiele krajów pozostało jednak zależnych od eksportu jednego surowca i od pomocy dawnych metropolii, a korupcja i wojny niszczyły dorobek gospodarczy. Mówi się wręcz o neokolonializmie.\n\n'
     'W aspekcie społecznym niepodległość oznaczała koniec dyskryminacji rasowej ze strony kolonizatorów i budowę własnego szkolnictwa. Narody odzyskiwały godność i mogły rozwijać własną kulturę i języki. Ceną były jednak masowe migracje (np. między Indiami a Pakistanem), wojny domowe, a w niektórych krajach — ludobójstwa, jak w Rwandzie (1994), którego korzenie sięgały polityki kolonialnej.\n\n'
     'Przeciwnicy tezy wskazują, że w wielu państwach poziom życia po uzyskaniu niepodległości przez dekady się nie poprawił. To prawda, ale przyczyną było w dużej mierze dziedzictwo kolonializmu, a nie sama niepodległość.\n\n'
     'Dekolonizacja zmieniła też ONZ: liczba państw członkowskich wzrosła z 51 w 1945 r. do ponad 150 w latach 70., a byłe kolonie zyskały głos w sprawach światowych.\n\n'
     'Podsumowując, dekolonizacja nie rozwiązała wszystkich problemów, ale dała narodom Azji i Afryki wolność i prawo do własnej drogi. Dlatego uważam, że przyniosła więcej korzyści niż strat.',
     'Plan: stanowisko „tak” → polityczny (niepodległość, ONZ, niezaangażowani / konflikty, dyktatury) → gospodarczy (nacjonalizacje, OPEC, Indie / zależność, neokolonializm) → społeczny (godność, szkoły / migracje, Rwanda) → kontrargument → wniosek.\n\nTypowe błędy: ograniczanie się do jednego kontynentu; brak konkretnych państw i dat.')),

 B('Wypracowanie — świat po 1945 r.: integracja europejska', M,
   T('wypracowanie', 15, 'Integracja europejska w latach 1950–1993 była przede wszystkim projektem gospodarczym. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt gospodarczy, polityczny i bezpieczeństwa.',
     'Modelowa odpowiedź (stanowisko: integracja przybrała formę gospodarczą, ale jej głównym celem był cel polityczny — trwały pokój).\n\n'
     'Proces integracji europejskiej rozpoczął się od deklaracji Roberta Schumana z 9 maja 1950 r., a jego kolejnym ważnym etapem był traktat z Maastricht (1992), który w 1993 r. powołał Unię Europejską. Uważam, że choć integracja rozwijała się głównie poprzez gospodarkę, nie była przede wszystkim projektem gospodarczym — gospodarka była narzędziem do osiągnięcia celów politycznych.\n\n'
     'W aspekcie gospodarczym widać, dlaczego teza może się wydawać prawdziwa. Pierwszą wspólnotą była Europejska Wspólnota Węgla i Stali (1951), a traktaty rzymskie (1957) powołały Europejską Wspólnotę Gospodarczą ze wspólnym rynkiem i Euratom. Wprowadzono unię celną (1968), wspólną politykę rolną, a Jednolity Akt Europejski (1986) zapowiedział rynek wewnętrzny ze swobodnym przepływem towarów, usług, kapitału i osób. Integracja przyniosła państwom członkowskim szybki wzrost gospodarczy.\n\n'
     'W aspekcie politycznym cele były jednak od początku szersze. Schuman pisał, że połączenie przemysłu węglowego i stalowego Francji i Niemiec ma uczynić wojnę między nimi „nie tylko nie do pomyślenia, ale materialnie niemożliwą”. Ojcowie założyciele — Schuman, Monnet, Adenauer, De Gasperi — chcieli pojednania narodów i trwałego pokoju. Z czasem pojawiły się instytucje polityczne: od 1979 r. Parlament Europejski wybierany w wyborach bezpośrednich, a Maastricht wprowadził obywatelstwo Unii i wspólną politykę zagraniczną.\n\n'
     'W aspekcie bezpieczeństwa integracja była odpowiedzią na zimną wojnę. Zjednoczona Europa Zachodnia miała być silniejsza wobec zagrożenia ze strony ZSRS, a włączenie RFN do wspólnot pozwalało kontrolować jej odbudowę. Bezpieczeństwo militarne zapewniało jednak przede wszystkim NATO, a projekt Europejskiej Wspólnoty Obronnej upadł w 1954 r.\n\n'
     'Zwolennicy tezy przypominają, że do lat 90. wspólnoty zajmowały się głównie handlem i rolnictwem. To prawda, ale była to świadoma metoda „małych kroków”, prowadząca do celu politycznego.\n\n'
     'Na polityczny charakter integracji wskazuje też jej rozszerzanie: przyjęcie Grecji (1981) oraz Hiszpanii i Portugalii (1986) miało przede wszystkim umocnić młode demokracje, które dopiero co wyszły z dyktatur. Względy gospodarcze były tu mniej ważne niż polityczne.\n\n'
     'Podsumowując, integracja europejska rozwijała się przez gospodarkę, ale jej istotą było pojednanie, pokój i budowa wspólnoty politycznej. Dlatego uważam tezę za tylko częściowo prawdziwą.',
     'Plan: stanowisko „forma gospodarcza, cel polityczny” → gospodarczy (EWWiS 1951, traktaty rzymskie 1957, unia celna 1968, JAE 1986) → polityczny (deklaracja Schumana, ojcowie założyciele, PE 1979, Maastricht) → bezpieczeństwo (zimna wojna, RFN, NATO, upadek EWO 1954) → kontrargument → wniosek.\n\nTypowe błędy: mylenie Rady Europy (1949) z EWG; podawanie dat traktatów bez wyjaśnienia ich znaczenia.')),

 B('Wypracowanie — Polska po 1945 r.: przejęcie władzy przez komunistów', M,
   T('wypracowanie', 15, 'W latach 1944–1948 komuniści przejmowali władzę w Polsce stopniowo, łącząc pozory demokracji z terrorem. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt polityczny, aparatu przemocy i społeczno-gospodarczy.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa).\n\n'
     'W lipcu 1944 r. w Lublinie ogłoszono manifest Polskiego Komitetu Wyzwolenia Narodowego, a w grudniu 1948 r. połączenie PPR i PPS w PZPR zakończyło budowę systemu komunistycznego. Uważam, że w tym okresie komuniści przejmowali władzę stopniowo, zachowując pozory pluralizmu, a w rzeczywistości opierając się na terrorze i wsparciu ZSRS.\n\n'
     'W aspekcie politycznym komuniści starali się wyglądać na szeroką koalicję. Po konferencji w Jałcie (1945) powstał Tymczasowy Rząd Jedności Narodowej, do którego wszedł Stanisław Mikołajczyk, przywódca PSL — jedynej dużej legalnej partii opozycyjnej. Jednak kluczowe resorty (bezpieczeństwo, wojsko) pozostały w rękach komunistów. Referendum „3 razy tak” (1946) i wybory do Sejmu Ustawodawczego (styczeń 1947) zostały sfałszowane, a ich oficjalne wyniki dały zwycięstwo blokowi komunistów. Mikołajczyk w 1947 r. musiał uciekać z kraju.\n\n'
     'Fundamentem władzy był aparat przemocy. Urząd Bezpieczeństwa i NKWD aresztowały żołnierzy AK i działaczy podziemia; przywódców Państwa Podziemnego Sowieci porwali i osądzili w Moskwie (proces szesnastu, 1945). Podziemie niepodległościowe walczyło jeszcze przez kilka lat, ale było systematycznie rozbijane, a jego żołnierzy skazywano na śmierć, jak rotmistrza Witolda Pileckiego (1948). Represje dotykały także członków PSL.\n\n'
     'W aspekcie społeczno-gospodarczym komuniści zyskiwali poparcie części społeczeństwa reformami. Dekret o reformie rolnej (1944) dał ziemię chłopom, a ustawa o nacjonalizacji przemysłu (1946) upaństwowiła zakłady zatrudniające ponad 50 pracowników. Odbudowa kraju i zasiedlanie Ziem Odzyskanych dawały ludziom pracę i nadzieję. Równocześnie „bitwa o handel” (1947) niszczyła prywatną przedsiębiorczość.\n\n'
     'Można argumentować, że komuniści nie musieli niczego udawać, bo za nimi stała Armia Czerwona. Pozory demokracji były jednak potrzebne ze względu na zobowiązania jałtańskie wobec Zachodu i by uzyskać choćby częściowe przyzwolenie społeczeństwa.\n\n'
     'Warto dodać, że komuniści przejmowali też kontrolę nad innymi partiami od środka: PPS została podporządkowana i oczyszczona z przeciwników współpracy z PPR, a Stronnictwo Pracy i Stronnictwo Demokratyczne stały się satelitami. Gdy w 1948 r. z PPR usunięto Władysława Gomułkę za „odchylenie prawicowo-nacjonalistyczne”, system był już w pełni podporządkowany Moskwie.\n\n'
     'Podsumowując, droga komunistów do pełni władzy była stopniowa i łączyła fasadę demokracji, popularne reformy i terror. Dlatego uważam tezę za prawdziwą.',
     'Plan: stanowisko „tak” → polityczny (PKWN, TRJN, Mikołajczyk, referendum 1946, wybory 1947, ucieczka Mikołajczyka) → aparat przemocy (UB, NKWD, proces szesnastu, podziemie, Pilecki) → społeczno-gospodarczy (reforma rolna, nacjonalizacja, Ziemie Odzyskane, bitwa o handel) → kontrargument → wniosek z PZPR 1948.\n\nTypowe błędy: mylenie dat referendum (1946) i wyborów (1947); pomijanie roli PSL.')),

 B('Wypracowanie — Polska po 1945 r.: „Solidarność” 1980–1981', M,
   T('wypracowanie', 15, '„Solidarność” w latach 1980–1981 była czymś więcej niż związkiem zawodowym. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt polityczny, społeczny i kulturowo-religijny.',
     'Modelowa odpowiedź (stanowisko: teza jest prawdziwa).\n\n'
     'Niezależny Samorządny Związek Zawodowy „Solidarność” powstał we wrześniu 1980 r., po strajkach sierpniowych i porozumieniach w Gdańsku, Szczecinie i Jastrzębiu. W ciągu kilku miesięcy liczył około 10 milionów członków. Uważam, że był czymś znacznie więcej niż związkiem zawodowym — stał się ruchem społecznym i politycznym, który zakwestionował monopol partii komunistycznej.\n\n'
     'W aspekcie politycznym już 21 postulatów strajkujących wykraczało poza sprawy pracownicze: domagano się wolnych związków zawodowych, prawa do strajku, wolności słowa i zniesienia cenzury, uwolnienia więźniów politycznych. Sam fakt istnienia legalnej, niezależnej od partii organizacji był w systemie komunistycznym wyłomem. I Krajowy Zjazd Delegatów (1981) przyjął program „Samorządnej Rzeczypospolitej” i „Posłanie do ludzi pracy Europy Wschodniej”, co Moskwa uznała za prowokację. Władze traktowały „Solidarność” jako polityczną konkurencję, czego dowodem było wprowadzenie stanu wojennego 13 grudnia 1981 r.\n\n'
     'W aspekcie społecznym „Solidarność” łączyła robotników, inteligencję i chłopów. Powstała „Solidarność” Rolników Indywidualnych, a niezależne zrzeszenie studentów (NZS) zostało zarejestrowane w 1981 r. Ekspertami związku byli intelektualiści, m.in. Tadeusz Mazowiecki i Bronisław Geremek, a doradcami — dawni działacze opozycji z KOR. Ruch odbudowywał więzi społeczne i samorządność, których brakowało w PRL.\n\n'
     'W aspekcie kulturowo-religijnym ruch był głęboko związany z Kościołem. Wybór Karola Wojtyły na papieża (1978) i jego pielgrzymka do Polski (1979) dały ludziom poczucie siły. Strajkujący w stoczni modlili się i spowiadali, a Lech Wałęsa podpisał porozumienie długopisem z wizerunkiem papieża. „Solidarność” odwoływała się do pamięci o Grudniu 1970 r. — w Gdańsku odsłonięto pomnik poległych stoczniowców.\n\n'
     'Można argumentować, że formalnie „Solidarność” była związkiem zawodowym i nie dążyła do przejęcia władzy, a jej przywódcy mówili o „samoograniczającej się rewolucji”. To prawda, ale zakres jej działalności i wpływ na społeczeństwo wykraczały daleko poza rolę związku.\n\n'
     'Skala ruchu była bez precedensu w bloku wschodnim: w żadnym innym państwie komunistycznym nie powstała legalna organizacja niezależna od partii, zrzeszająca co trzeciego dorosłego obywatela.\n\n'
     'Podsumowując, „Solidarność” była ruchem społecznym obejmującym miliony ludzi, wyrazem dążeń politycznych i kulturowych Polaków. Dlatego uważam tezę za prawdziwą.',
     'Plan: stanowisko „tak” → polityczny (21 postulatów, monopol partii, zjazd 1981, stan wojenny) → społeczny (10 mln, robotnicy + inteligencja + chłopi + studenci, KOR, eksperci) → kulturowo-religijny (papież 1978–1979, modlitwa w stoczni, pamięć Grudnia ’70) → kontrargument („samoograniczająca się rewolucja”) → wniosek.\n\nTypowe błędy: opis wyłącznie strajków sierpniowych; mylenie porozumień z 1980 r. z Okrągłym Stołem (1989).')),

 B('Wypracowanie — Polska po 1945 r.: przemiany 1989 r.', M,
   T('wypracowanie', 15, 'Przemiany ustrojowe w Polsce w 1989 r. były przede wszystkim wynikiem czynników wewnętrznych. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji aspekt polityczny, gospodarczy i międzynarodowy.',
     'Modelowa odpowiedź (stanowisko: czynniki wewnętrzne były kluczowe, ale bez zmian w ZSRS przemiany nie byłyby możliwe — teza jest częściowo prawdziwa).\n\n'
     'W 1989 r. Polska jako pierwsza w bloku wschodnim pokojowo odeszła od komunizmu: obrady Okrągłego Stołu (luty–kwiecień), częściowo wolne wybory 4 czerwca i powołanie rządu Tadeusza Mazowieckiego (wrzesień). Uważam, że decydujące były czynniki wewnętrzne — opór społeczeństwa i kryzys gospodarczy — ale nie doszłoby do nich bez sprzyjającej sytuacji międzynarodowej.\n\n'
     'W aspekcie politycznym najważniejszy był trwały opór społeczeństwa. Mimo stanu wojennego i delegalizacji „Solidarności” podziemie działało przez całe lata 80., wydawało prasę i organizowało protesty. Fale strajków w 1988 r. przekonały władze, że bez porozumienia z opozycją nie opanują sytuacji. Ważną rolę odegrał też Kościół, który pośredniczył w rozmowach (spotkania w Magdalence), oraz pielgrzymki Jana Pawła II, umacniające postawy społeczne.\n\n'
     'W aspekcie gospodarczym PRL była w głębokim kryzysie. Zadłużenie zagraniczne, zaciągnięte w latach 70., przekraczało możliwości spłaty, sklepy były puste, obowiązywały kartki, a inflacja rosła. Reformy rządów Zbigniewa Messnera i Mieczysława Rakowskiego nie przyniosły poprawy. Władze rozumiały, że bez poparcia społecznego nie przeprowadzą bolesnych reform — stąd zgoda na podzielenie się odpowiedzialnością z opozycją.\n\n'
     'W aspekcie międzynarodowym kluczowe były zmiany w ZSRS. Michaił Gorbaczow, wprowadzając pierestrojkę i głasnost, porzucił doktrynę Breżniewa — Moskwa nie zamierzała już interweniować zbrojnie w państwach bloku. Stany Zjednoczone i Europa Zachodnia wspierały opozycję i uzależniały pomoc gospodarczą od reform. W 1981 r. groźba interwencji była jednym z argumentów za stanem wojennym; w 1989 r. tej groźby zabrakło.\n\n'
     'Zwolennicy przeciwnego poglądu wskazują, że bez Gorbaczowa władze PRL mogłyby po raz kolejny sięgnąć po siłę. To ważny argument, ale sam Gorbaczow nie zmusił polskich komunistów do rozmów — zrobiło to społeczeństwo i kryzys.\n\n'
     'Znaczenie miał też przykład innych krajów: w tym samym roku na Węgrzech toczyły się podobne rozmowy, a jesienią upadł mur berliński. Polska była jednak pierwsza, a jej droga — rozmowy przy Okrągłym Stole i kontraktowe wybory — stała się wzorem dla sąsiadów.\n\n'
     'Podsumowując, przemiany 1989 r. były przede wszystkim dziełem Polaków, ale ich powodzenie umożliwiła nowa polityka ZSRS. Dlatego teza jest prawdziwa tylko częściowo.',
     'Plan: stanowisko „częściowo” → polityczny (podziemie, strajki 1988, Kościół, Magdalenka) → gospodarczy (zadłużenie, kartki, inflacja, nieudane reformy) → międzynarodowy (Gorbaczow, doktryna Breżniewa, Zachód) → kontrargument → wniosek.\n\nTypowe błędy: pisanie, że wybory 4 czerwca były w pełni wolne (do Sejmu obowiązywał kontrakt: 65% miejsc dla koalicji rządzącej); pomijanie kryzysu gospodarczego.')),

 B('Wypracowanie — temat przekrojowy: Kościół w dziejach Polski', M,
   T('wypracowanie', 15, 'W dziejach Polski Kościół katolicki odgrywał przede wszystkim rolę polityczną. Zajmij stanowisko wobec powyższej tezy i je uzasadnij, uwzględniając w swojej argumentacji trzy wybrane okresy: średniowiecze, okres zaborów i okres PRL.',
     'Modelowa odpowiedź (stanowisko: rola polityczna była ważna, ale w każdym okresie równie ważna była rola kulturowa i narodowa — teza jest tylko częściowo prawdziwa).\n\n'
     'Od chrztu Mieszka I w 966 r. Kościół katolicki towarzyszył państwu polskiemu przez ponad tysiąc lat. Uważam, że rzeczywiście często odgrywał rolę polityczną, ale nie była ona najważniejsza: w kluczowych momentach Kościół był przede wszystkim strażnikiem kultury i tożsamości narodowej.\n\n'
     'W średniowieczu rola polityczna Kościoła była ogromna. Chrzest wprowadził państwo Mieszka do kręgu chrześcijańskiej Europy i utrudnił Niemcom uzasadnianie podbojów misją. Utworzenie arcybiskupstwa w Gnieźnie (1000) uniezależniło polski Kościół od niemieckiego. W okresie rozbicia dzielnicowego arcybiskupi, zwłaszcza Jakub Świnka, wspierali zjednoczenie, koronując Przemysła II (1295). Jednocześnie Kościół był głównym ośrodkiem kultury: klasztory i szkoły katedralne, kroniki (Gall Anonim, Wincenty Kadłubek), pierwsze teksty polskie.\n\n'
     'W okresie zaborów, gdy nie było państwa, Kościół stał się jedną z głównych instytucji narodowych. W zaborze pruskim, w czasie Kulturkampfu, wiara katolicka chroniła przed germanizacją (uwięzienie abp. Ledóchowskiego, strajk we Wrześni w obronie lekcji religii po polsku). W zaborze rosyjskim katolicyzm odróżniał Polaków od prawosławnych Rosjan, a duchowni uczestniczyli w powstaniach — np. ks. Stanisław Brzóska w powstaniu styczniowym. Była to rola narodowa i kulturowa bardziej niż ściśle polityczna.\n\n'
     'W okresie PRL Kościół był jedyną dużą instytucją niezależną od władzy. Prymas Stefan Wyszyński, więziony w latach 1953–1956, stał się symbolem oporu, a obchody Milenium Chrztu (1966) zgromadziły miliony ludzi. Wybór Karola Wojtyły na papieża (1978) i pielgrzymka z 1979 r. przyczyniły się do narodzin „Solidarności”. Kościół pośredniczył w rozmowach władzy z opozycją w 1989 r. Zarazem jego hierarchowie unikali otwartego udziału w polityce, mówiąc o obronie praw człowieka i godności.\n\n'
     'Można argumentować, że skoro Kościół wpływał na koronacje, powstania i upadek komunizmu, jego rola była przede wszystkim polityczna. Jednak jego wpływ wynikał z autorytetu religijnego i kulturowego, a nie z politycznej siły.\n\n'
     'W każdym z tych okresów Kościół prowadził także szkoły i działalność charytatywną, co dodatkowo wzmacniało jego autorytet.\n\n'
     'Podsumowując, Kościół odgrywał w dziejach Polski rolę polityczną, ale jego najważniejszą funkcją było podtrzymywanie tożsamości narodowej i kultury. Dlatego teza jest tylko częściowo prawdziwa.',
     'Plan: stanowisko „częściowo” → średniowiecze (chrzest 966, Gniezno 1000, Świnka i 1295, kultura) → zabory (Kulturkampf, Ledóchowski, Września, prawosławie, ks. Brzóska) → PRL (Wyszyński, Milenium 1966, papież 1978/1979, 1989) → kontrargument → wniosek.\n\nTypowe błędy: w temacie przekrojowym brak równowagi między okresami (każdy musi mieć przykłady); ogólniki bez nazwisk i dat.')),
]
